"""Warn about commit subjects the changelog would skip. Never fails the build.

Usage: check_commit_messages.py <base-ref>     (checks <base-ref>..HEAD)

The changelog is generated by release-please from commit subjects written as

    type(optional scope): summary          e.g.  feat(sites): add a second site adapter

Subjects that do not look like that are not an error, they just do not appear in
CHANGELOG.md. This script says so, so it is noticed before the merge and not after.
"""

import os
import re
import subprocess
import sys

TYPES = "feat|fix|perf|refactor|docs|test|chore|ci|build|style|revert"
PATTERN = re.compile(rf"^({TYPES})(\([A-Za-z0-9_./,-]+\))?!?: \S")
MAX_SUBJECT = 100


def subjects(base: str) -> list[str]:
    """``<short sha> <subject>`` for every non-merge commit in ``base..HEAD``."""
    out = subprocess.run(
        ["git", "log", "--no-merges", "--format=%h %s", f"{base}..HEAD"],
        capture_output=True,
        text=True,
        check=True,
    ).stdout
    return [line for line in out.splitlines() if line.strip()]


def problem_with(sha: str, subject: str) -> str | None:
    """What is wrong with one subject, or None if it is fine."""
    if not PATTERN.match(subject):
        return f"{sha}: not `type: summary` form, left out of the changelog: {subject}"
    if len(subject) > MAX_SUBJECT:
        return (
            f"{sha}: subject is {len(subject)} characters (keep it under {MAX_SUBJECT}): {subject}"
        )
    return None


def report(base: str, commits: list[str], problems: list[str]) -> str:
    verdict = "Everything is in the right form." if not problems else f"{len(problems)} to look at:"
    lines = [f"Checked {len(commits)} commit(s) against {base}.", verdict]
    return "\n".join(lines + [f"- {p}" for p in problems])


def publish(text: str, problems: list[str]) -> None:
    """Print the report, add workflow warnings, and append to the job summary if available."""
    print(text)
    for problem in problems:
        print(f"::warning title=Commit message::{problem}")
    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary:
        with open(summary, "a", encoding="utf-8") as handle:
            handle.write(text + "\n")


def main() -> int:
    base = sys.argv[1] if len(sys.argv) > 1 else "origin/main"
    try:
        commits = subjects(base)
    except subprocess.CalledProcessError as exc:
        print(f"Could not list commits against {base}: {exc.stderr.strip()}")
        return 0
    checked = (line.partition(" ") for line in commits)
    problems = [p for sha, _, subject in checked if (p := problem_with(sha, subject))]
    publish(report(base, commits, problems), problems)
    return 0


if __name__ == "__main__":
    sys.exit(main())
